// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testRegression_property() public {
        // Pre-deploy a reward token address (any non-zero address works)
        address rewardToken = address(0x1234);
        // Since constructor sets owner to msg.sender (the test contract),
        // we use vm.prank(address(this)) to be the owner
        vm.prank(address(this));
        bool ok;
        try c.addReward(rewardToken) {
            ok = true;
        } catch {
            ok = false;
        }
        // In the reference contract, owner() returns the actual owner (address(this)),
        // so onlyOwner passes and addReward succeeds => ok is true.
        // In the mutant, owner() always returns address(0), so onlyOwner reverts => ok is false.
        assertTrue(ok);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testRegression_property() public {
        // No special setup needed; addReward on a non-zero address
        address rewardToken = address(0x123);
        c.addReward(rewardToken);

        // Now test transferOwnership: reference requires newOwner != address(0); mutant requires newOwner == address(0)
        address newOwner = address(0x456);

        bool success;
        try c.transferOwnership(newOwner) {
            success = true;
        } catch {
            success = false;
        }

        // In reference, this succeeds; in mutant, it reverts because newOwner != address(0)
        assertTrue(success, "Reference succeeds, mutant should revert");
    }
}

