pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testRegression_property() public {
        // setRewardDistributor is called in the constructor with address(this)
        // For the buggy version, _transferOwnership(address(this)) changes owner to address(this)
        // For the reference, rewardDistributor is set to address(this)

        // addReward will cause the difference in rewardDistributor state
        c.addReward(address(0x1));

        // The reference has rewardDistributor = address(this)
        // The buggy version has rewardDistributor = address(0) (default) because _transferOwnership doesn't affect it
        assertTrue(c.rewardDistributor() == address(this));
    }
}

