contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testRegression_property() public {
        // Call addReward on an arbitrary token
        address rewardToken = address(0x1234);
        c.addReward(rewardToken);
        // Reward distributor should still be address(this) (as set in constructor) for reference,
        // but in the bug it remains address(0) because setRewardDistributor never assigned it.
        // Since constructor set rewardDistributor = address(this) in both versions,
        // and addReward does not change rewardDistributor, both will return address(this).
        // Wait — the bug is that setRewardDistributor (if called) would change ownership.
        // But we never call setRewardDistributor in this test. The constructor sets rewardDistributor
        // to address(this) in both versions. So after addReward they still match.
        // This test fails to distinguish. I need a different concrete scenario.
        // Let me call setRewardDistributor to a new address, then observe rewardDistributor.
        // In reference, rewardDistributor changes to newDistributor. In bug, it stays address(this).
        address newDistributor = address(0xDEAD);
        c.setRewardDistributor(newDistributor);
        assertTrue(c.rewardDistributor() == newDistributor, "rewardDistributor should be updated");
