pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testRegression_property() public {
        // Setup: add a reward token
        address rewardToken = address(0x1234);
        c.addReward(rewardToken);

        // Now check claimableRewards of a user that never staked (e.g. address(this))
        // In the reference version, claimableRewards[user][rewardToken] should be 0
        // In the buggy version, the updateReward modifier in addReward incorrectly updated it
        uint256 claimable = c.claimableRewards(address(this), rewardToken);
        assertTrue(claimable == 0, "Claimable should be zero for non-staker");
    }
}

