pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    mapping(address => uint256) _balances;
    mapping(address => mapping(address => uint256)) _allowances;
    uint256 _totalSupply;

    // ERC20 functions for address(this) acting as the staking token
    function totalSupply() external view returns (uint256) { return _totalSupply; }
    function balanceOf(address account) external view returns (uint256) { return _balances[account]; }
    function transfer(address to, uint256 amount) external returns (bool) {
        _balances[msg.sender] -= amount;
        _balances[to] += amount;
        return true;
    }
    function allowance(address owner, address spender) external view returns (uint256) { return _allowances[owner][spender]; }
    function approve(address spender, uint256 amount) external returns (bool) {
        _allowances[msg.sender][spender] = amount;
        return true;
    }
    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        _allowances[from][msg.sender] -= amount;
        _balances[from] -= amount;
        _balances[to] += amount;
        return true;
    }

    // Mint function for setup
    function mint(address to, uint256 amount) external {
        _balances[to] += amount;
        _totalSupply += amount;
    }

    C c;

    function setUp() public {
        c = new C(address(this), address(this));
        // Mint tokens to the test contract (distributor) for rewards
        this.mint(address(this), 2000);
        // Mint tokens to staker
        this.mint(address(0x456), 200);
    }

    function testRegression_property() public {
        address staker = address(0x456);
        address rewardToken = address(0x123);

        // Add reward token
        c.addReward(rewardToken);

        // Approve C to spend staker's tokens
        vm.prank(staker);
        this.approve(address(c), 100);

        // Stake 100 tokens as staker
        vm.prank(staker);
        c.stake(100);

        // Approve C to spend distributor's reward tokens
        this.approve(address(c), 1000);

        // Notify reward of 1000 tokens
        c.notifyRewardAmount(rewardToken, 1000);

        // Warp forward 1 second to allow reward accumulation
        vm.warp(block.timestamp + 1);

        // Now P.rewardPerToken(rewardToken) should be > 0 because:
        // rewardRate = 1000 / 604800 ≈ 0.00165
        // lastUpdateTime = block.timestamp (after notify)
        // rewardPerTokenStored = 0 initially
        // (lastTimeRewardApplicable - lastUpdateTime) = 1
        // So rewardPerToken = 0 + (1 * 0.00165 * 1e18) / 100 ≈ 1.65e13 / 100? Actually (1 * 0.00165 * 1e18) / 100 = (1.65e15) / 100 = 1.65e13
        // So it's a positive number.
        // M always returns 0.
        uint256 pRewardPerToken = c.rewardPerToken(rewardToken);
        assertTrue(pRewardPerToken > 0, "rewardPerToken should be > 0");
    }
}

